      $('#user-sex-anus').text(_.get(userSex, '肛门', ['N/A'])[0]);
      $('#user-pose').text(_.get(user, '当前姿势', ['N/A'])[0]);
      $('#user-action').text(_.get(user, '当前行动', ['N/A'])[0]);

      // === 其他角色状态 (所有角色动态生成) ===
      const npcTemplate = $('#npc-template'); // 获取隐藏的模板

      Object.entries(characters).forEach(([charName, charData]) => {
        if (charName.startsWith('$')) return; // 过滤元数据
        if (charName === '{{user}}') { return; } // 过滤{{user}}

        // 克隆模板，并设置ID和显示名称
        const charPanel = npcTemplate.clone();
        charPanel.attr('id', `char-panel-${charName}`);
        charPanel.find('.char-name').text(charName);
        charPanel.css('display', 'block'); // 显示克隆的模板

        // 填充数据
        fillCharacterPanel(charPanel, charData);

        charactersList.append(charPanel); // 添加到列表中
      });
